{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.money import Money"
  ],
  "tests": [
    {
      "name": "test_allocate_example_from_task",
      "intent": "the example given in the task: 100.00 split into three equal parts yields 33.34, 33.33, 33.33",
      "code": "# intent: the example given in the task: 100.00 split into three equal parts yields 33.34, 33.33, 33.33\ndef test_allocate_example_from_task():\n    result = Money.of('100.00').allocate([1, 1, 1])\n    assert result == [Money.of('33.34'), Money.of('33.33'), Money.of('33.33')]\n"
    },
    {
      "name": "test_allocate_parts_sum_to_total",
      "intent": "allocated parts always add up to the original amount",
      "code": "# intent: allocated parts always add up to the original amount\ndef test_allocate_parts_sum_to_total():\n    total = Money.of('100.00')\n    parts = total.allocate([1, 1, 1])\n    assert sum((p.amount for p in parts), Decimal('0.00')) == total.amount\n"
    },
    {
      "name": "test_allocate_leftover_distributed_to_earliest_nonzero_ratio",
      "intent": "leftover cents are handed out one at a time to the earliest parts with non-zero ratio",
      "code": "# intent: leftover cents are handed out one at a time to the earliest parts with non-zero ratio\ndef test_allocate_leftover_distributed_to_earliest_nonzero_ratio():\n    result = Money.of('0.05').allocate([1, 1, 1])\n    assert result == [Money.of('0.02'), Money.of('0.02'), Money.of('0.01')]\n"
    },
    {
      "name": "test_allocate_zero_ratio_parts_get_nothing",
      "intent": "parts with zero ratio receive zero amount",
      "code": "# intent: parts with zero ratio receive zero amount\ndef test_allocate_zero_ratio_parts_get_nothing():\n    result = Money.of('1.00').allocate([0, 1, 0])\n    assert result == [Money.of('0.00'), Money.of('1.00'), Money.of('0.00')]\n"
    },
    {
      "name": "test_allocate_all_zero_ratios_raises_value_error",
      "intent": "allocating with all zero ratios raises ValueError",
      "code": "# intent: allocating with all zero ratios raises ValueError\ndef test_allocate_all_zero_ratios_raises_value_error():\n    with pytest.raises(ValueError):\n        Money.of('1.00').allocate([0, 0])\n"
    },
    {
      "name": "test_allocate_negative_ratio_raises_value_error",
      "intent": "allocating with a negative ratio raises ValueError",
      "code": "# intent: allocating with a negative ratio raises ValueError\ndef test_allocate_negative_ratio_raises_value_error():\n    with pytest.raises(ValueError):\n        Money.of('1.00').allocate([1, -1])\n"
    }
  ]
}
